import { isArray } from "../../core/helpers/checker/is-array.js";
import { isJoditObject } from "../../core/helpers/checker/is-jodit-object.js";
import { attr } from "../../core/helpers/utils/attr.js";
import { Config } from "../../config.js";
import { getItems } from "./helpers/normalize-uploader-data.js";
/**
 * Module for processing download documents and images by Drag and Drop
 * Drag and Drop files
 */
Config.prototype.enableDragAndDropFileToEditor = true;
Config.prototype.uploader = {
    url: '',
    insertImageAsBase64URI: false,
    showTabInFileSelector: true,
    imagesExtensions: [
        'jpg',
        'jpeg',
        'png',
        'gif',
        'webp',
        'bmp',
        'svg',
        'tiff',
        'avif'
    ],
    headers: null,
    data: null,
    filesVariableName(i) {
        return `files[${i}]`;
    },
    withCredentials: false,
    pathVariableName: 'path',
    format: 'json',
    method: 'POST',
    prepareData(formData) {
        return formData;
    },
    isSuccess(resp) {
        return resp.success;
    },
    getMessage(resp) {
        return resp.data.messages !== undefined && isArray(resp.data.messages)
            ? resp.data.messages.join(' ')
            : '';
    },
    /**
     * @see [[IUploader.processFileName]]
     */
    processFileName(key, file, name) {
        return [key, file, name];
    },
    process(resp) {
        return resp.data;
    },
    error(e) {
        this.j.message.error(e.message, 4000);
    },
    getDisplayName(baseurl, filename) {
        return baseurl + filename;
    },
    defaultHandlerSuccess(resp) {
        const j = this.j || this;
        if (!isJoditObject(j)) {
            return;
        }
        const { baseurl } = resp;
        getItems(resp).forEach(({ file, isImage }) => {
            const [tagName, attrName] = isImage
                ? ['img', 'src']
                : ['a', 'href'];
            const elm = j.createInside.element(tagName);
            attr(elm, attrName, baseurl + file);
            if (tagName === 'a') {
                elm.textContent = j.o.uploader.getDisplayName.call(this, baseurl, file);
            }
            if (tagName === 'img') {
                j.s.insertImage(elm, null, j.o.imageDefaultWidth);
            }
            else {
                j.s.insertNode(elm);
            }
        });
    },
    defaultHandlerError(e) {
        this.j.message.error(e.message);
    },
    promptOnExists: true,
    promptOnExistsSuggestName(name) {
        return name;
    },
    contentType(requestData) {
        return this.ow.FormData !== undefined &&
            typeof requestData !== 'string'
            ? false
            : 'application/x-www-form-urlencoded; charset=UTF-8';
    }
};
